import json, re

filepath = "/home/david/projects/pi-pos-v1/.pi/maestro/sessions/223/builder-reviewer-reviewer-2026-05-30T14:55:57.jsonl/2026-05-30T14-55-57-771Z_019e7962-7b4a-74ed-ad24-5652473c014e.jsonl"

with open(filepath, 'r') as f:
    for line in f:
        obj = json.loads(line)
        if obj.get('type') == 'message' and obj['message'].get('role') == 'assistant':
            content = obj['message']['content']
            for item in content:
                if item.get('type') == 'text':
                    text = item['text']
                    if '```verdict' in text.lower():
                        print("FOUND verdict block!")
                        # Extract JSON from code block
                        match = re.search(r'\`\`\`verdict\s*\n(.*?)\n?\s*\`\`\`', text, re.DOTALL)
                        if match:
                            json_str = match.group(1).strip()
                            try:
                                parsed = json.loads(json_str)
                                print(f"JSON valid. Status: {parsed.get('status')}, Verdict: {parsed.get('verdict')}")
                            except json.JSONDecodeError as e:
                                print(f"JSON INVALID: {e}")
                                print(f"Raw JSON (first 300 chars): {json_str[:300]}")
                        else:
                            print("Could not extract code block content")
